package com.MITProjectAdmin.Controller.management;import com.MITProjectService.bot.Services.PaymentService;import com.MITProjectService.bot.dao.jpaRepos.specification.PaymentFilterSpecification;import com.MITProjectService.bot.domain.Payment;import com.MITProjectService.bot.request.PaymentRequest;import jakarta.annotation.Resource;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.domain.Specification;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;@RestController@RequestMapping("admin/payment")public class PaymentController {    @Resource    private PaymentService paymentService;    @PostMapping("/getAllPayments")    public ResponseEntity<?> getAllPayments(@RequestBody PaymentRequest paymentRequest) {        Pageable pageable = PageRequest.of(paymentRequest.getPage(), paymentRequest.getLimit());        Specification<Payment> filter = PaymentFilterSpecification.filter(paymentRequest);        return ResponseEntity.ok(paymentService.getPaymentsPage(pageable, filter));    }    @PostMapping("/validatePayment")    public ResponseEntity<?> validatePayment(@RequestBody PaymentRequest paymentRequest) {        return ResponseEntity.ok(paymentService.validatePayment(paymentRequest));    }}